%[text] # FMCW Radar Waveform Based Range Calculation Using Time Trigger
%[text] This example shows how to use time triggering with a B210 radio to calculate the range of a target using frequency-modulated continuous wave (FMCW) radar waveform.
%[text] ## Generate FMCW radar waveform
%[text] Set the sample rate, interpolation factor or decimation factor, and master clock rate.
Fs = 30e6; % Sample Rate
interpDecim  = 1; % Interpolation or Decimation factor of interest
masterClkRate = interpDecim*Fs; % Master clock rate
%[text] Set the sweep time and sweep bandwidth. Divide the sweep bandwidth by the sweep time to obtain the slope.
% Specify sweep time and sweep bandwidth
sweepTime = 1e-3;
sweepBW = 15e6;
slope = sweepBW/sweepTime;
%[text] Use the [`bw2rangeres`](docid:phased_ref#mw_b3a410a0-e01c-4d75-b41c-88a8dca63185) function to calculate the range resolution corresponding to the signal bandwidth and the [`time2range`](docid:phased_ref#btigzrl_1) function to calculate the maximum range the signal propagates during `sweepTime/6` seconds.
% Calculate the range resolution and maximum range
rangeRes = bw2rangeres(sweepBW);
fprintf('Range resolution = %d',rangeRes) %[output:6191ce94]
maxRange  = time2range(sweepTime/6);
fprintf('Maximum range = %d',maxRange) %[output:609908a2]
%[text] Create a [`phased.FMCWWaveform`](docid:phased_ref#ref_q1ush7jol) object.
hwav = phased.FMCWWaveform(SampleRate=Fs, SweepTime=sweepTime,...
                           SweepBandwidth=sweepBW, OutputFormat='Sweeps', NumSweeps=1);
%[text] Generate the FMCW radar waveform.
xRef =  hwav();
NumSamps = length(xRef);
%%
%[text] ## Set Transmitter Properties
%[text] Create a [`comm.SDRuTransmitter`](docid:usrpradio_ug#bun595a-1) object.
txGain = 45;
txChannelMapping = 1;

tx = comm.SDRuTransmitter(Platform = "B210", SerialNum='3136D5F', ...
    PPSSource = "Internal", ...
    ClockSource= "Internal", ...
    MasterClockRate=masterClkRate,...
    InterpolationFactor=interpDecim,...
    ChannelMapping=txChannelMapping,...
    Gain=txGain, CenterFrequency=3.21e9);
%[text] Set the `EnableTimeTrigger` property for the transmitter object as `true` and set the desired trigger time for transmission.
% Provide trigger time
usrpTriggerTime = 12;

tx.EnableTimeTrigger = true;
tx.TriggerTime = usrpTriggerTime;
%%
%[text] ## Set Receiver Properties
%[text] Create a [`comm.SDRuReceiver`](docid:usrpradio_ug#bun592c-1) object.
rxGain = 45;
rxChannelMapping = 2;

rx = comm.SDRuReceiver(Platform = "B210", SerialNum='3136D5F', ...
    PPSSource = "Internal", ...
    ClockSource= "Internal", ...
    MasterClockRate=masterClkRate,...
    DecimationFactor=interpDecim, ...
    SamplesPerFrame = NumSamps,...
    OutputDataType="double",...
    ChannelMapping=rxChannelMapping, Gain=rxGain,CenterFrequency=3.21e9);
%[text] Set the `EnableTimeTrigger` property for the receiver object as `true` and set the desired trigger time for reception.
rx.EnableTimeTrigger = true;
rx.TriggerTime = usrpTriggerTime; % Same as tx trigger time
%%
%[text] ## Set Timescope and Spectrumscope properties
%[text] Set the [`spectrumAnalyzer`](docid:dsp_ref#mw_d312d509-f3fe-49bd-9fe1-dd35c86ae976) and [`timescope`](docid:dsp_ref#mw_a35c8917-4fd1-4557-b840-f27aeb1567be) properties.
decimfact = 4;
spectrumScope1 = spectrumAnalyzer(SampleRate=Fs);
spectrumScope2 = spectrumAnalyzer(SampleRate=Fs/decimfact);
spectrumScope3 = spectrumAnalyzer(SampleRate=Fs/decimfact);

spectrumScope2.PeakFinder.Enabled = true;
spectrumScope3.PeakFinder.Enabled = true;

% Set the number of frames you would like to process
numFrames = 1;
frameTime = NumSamps/Fs;
timeSpan = numFrames*frameTime;

timeScope = timescope(SampleRate=Fs, ...
    TimeSpanSource="property", ...
    TimeSpan = timeSpan, ...
    LayoutDimensions=[2,1]);
%%
%[text] ## Transmit and Receive FMCW Radar Waveform
%[text] Transmit the FMCW radar waveform and receive the reflected FMCW radar waveform from the target after the specified trigger time.
yBuff = zeros(numFrames*NumSamps,1);
xRefBuff = zeros(numFrames*NumSamps,1);

for i=1:numFrames %[output:group:705db029]
    txData = hwav();
    underrun = tx(txData);
    if underrun==0
        disp('Transmission successful') %[output:6747d96c]
    else
        disp('Transmission failed')
    end
    % Receive the signal

    [rxdata, ~,overflow, rx_time_stamp] = rx();
    if overflow==0
        disp('Reception successful') %[output:3275c73f]
    else
        disp('Reception failed')
    end
    yDechirp = dechirp(rxdata,txData);
    yBuff((i-1)*NumSamps+1:i*NumSamps,1) = yDechirp;
   
    xRefBuff((i-1)*NumSamps+1:i*NumSamps,1) = txData;
   
    spectrumScope1(txData)
    spectrumScope2(decimate(yDechirp,decimfact))
end %[output:group:705db029]
%[text] ![fmcw1.png](text:image:9c09)
%[text] ## ![fmcw2.png](text:image:9f6f)Calculate the Range of the Target Based On the Beat Frequency
%[text] To calculate the beat frequency, use spectrum analyzer to find the peak frequency.
spectrumData1 = getMeasurementsData(spectrumScope2);
beatFreq = spectrumData1.PeakFinder.Frequency(1);
c = 3e8; % Speed of light
beatFreqRange = beat2range(beatFreq,slope,c);
fprintf('Range of the target based on beat frequency = %d',beatFreqRange) %[output:347bee7c]

timeScope(real(xRefBuff),real(yBuff));

%[text] ![fmcw3.png](text:image:4c8e)Release the timescope, spectrumscope, transmitter and receiver System objects.
release(timeScope);
release(spectrumScope1);
release(spectrumScope2);
release(rx);
release(tx);
